<?php

// The Rust port of `src/`, generated by everything-rust: the same functions, each calling the
// Rust library through PHP's FFI extension. Require it in place of the original files.
// Regenerate with `everything-rust refresh`.

namespace EverythingRust {
    if (!\class_exists(Codec::class, false)) {
        final class Codec
        {
            public const FLAGS = \JSON_PRESERVE_ZERO_FRACTION | \JSON_THROW_ON_ERROR
                | \JSON_UNESCAPED_SLASHES | \JSON_UNESCAPED_UNICODE;
            public const DEPTH = 100000;

            public static function enc($v)
            {
                if (\is_float($v)) {
                    if (\is_nan($v)) {
                        return ['$num' => 'NaN'];
                    }
                    if (\is_infinite($v)) {
                        return ['$num' => $v > 0 ? 'Infinity' : '-Infinity'];
                    }
                    if ($v == 0.0 && \fdiv(1.0, $v) < 0) {
                        return ['$num' => '-0'];
                    }
                    return $v;
                }
                if (\is_array($v)) {
                    $out = [];
                    foreach ($v as $k => $x) {
                        $out[$k] = self::enc($x);
                    }
                    return $out;
                }
                if (\is_object($v)) {
                    return ['$object' => \get_class($v)];
                }
                if (\is_resource($v)) {
                    return ['$resource' => \get_resource_type($v)];
                }
                return $v;
            }

            public static function dec($v)
            {
                if (!\is_array($v)) {
                    return $v;
                }
                if (\count($v) === 1 && \array_key_exists('$num', $v)) {
                    return ['NaN' => \NAN, 'Infinity' => \INF, '-Infinity' => -\INF, '-0' => -0.0][$v['$num']];
                }
                if (\count($v) === 1 && \array_key_exists('$undefined', $v)) {
                    return null;
                }
                $out = [];
                foreach ($v as $k => $x) {
                    $out[$k] = self::dec($x);
                }
                return $out;
            }

            public static function json($v): string
            {
                return \json_encode(self::enc($v), self::FLAGS);
            }

            /// `Err("InvalidArgumentException: message")` throws that class; anything else a
            /// RuntimeException.
            public static function error(string $message): \Throwable
            {
                if (\preg_match('/^\\\\?([A-Za-z_][A-Za-z0-9_]*(?:\\\\[A-Za-z_][A-Za-z0-9_]*)*): (.*)$/s', $message, $m)
                    && \class_exists($m[1])
                    && \is_subclass_of($m[1], \Throwable::class)
                ) {
                    try {
                        return new $m[1]($m[2]);
                    } catch (\Throwable $e) {
                    }
                }
                return new \RuntimeException($message);
            }
        }
    }
}

namespace EverythingRust {
    final class NativeXmlUtilRs
    {
        private static $ffi = null;

        public static function call(string $name, array $args)
        {
            if (self::$ffi === null) {
                $lib = \PHP_OS_FAMILY === 'Darwin' ? 'libxml_util_rs.dylib' : (\PHP_OS_FAMILY === 'Windows' ? 'xml_util_rs.dll' : 'libxml_util_rs.so');
                self::$ffi = \FFI::cdef(
                    'char *everything_rust_call(const char *name, const char *args); void everything_rust_free(char *ptr);',
                    __DIR__ . '/' . $lib
                );
            }
            $ptr = self::$ffi->everything_rust_call($name, Codec::json($args));
            if ($ptr === null) {
                throw new \RuntimeException("everything-rust: no answer from `$name`");
            }
            try {
                $text = \FFI::string($ptr);
            } finally {
                self::$ffi->everything_rust_free($ptr);
            }
            $answer = \json_decode($text, true, Codec::DEPTH, \JSON_THROW_ON_ERROR);
            if (\array_key_exists('ok', $answer)) {
                return Codec::dec($answer['ok']);
            }
            if (\array_key_exists('panic', $answer)) {
                throw new \Error('Rust panic: ' . $answer['panic']);
            }
            throw Codec::error((string) $answer['error']);
        }
    }
}

namespace XmlUtil {
    function replace_entities(string $string, int $replaceEntities = 1)
    {
        return \EverythingRust\NativeXmlUtilRs::call('replace_entities', [$string, $replaceEntities]);
    }

    function reverse_entities(string $string, int $replaceEntities = 1)
    {
        return \EverythingRust\NativeXmlUtilRs::call('reverse_entities', [$string, $replaceEntities]);
    }

    function attributes_to_string(
        array $attributes,
        bool $sort = true,
        bool $multiline = false,
        string $indent = '    ',
        string $linebreak = "\n",
        int $entities = 1
    )
    {
        return \EverythingRust\NativeXmlUtilRs::call('attributes_to_string', [$attributes, $sort, $multiline, $indent, $linebreak, $entities]);
    }

    function split_qualified_name(string $qname, ?string $defaultNs = null)
    {
        return \EverythingRust\NativeXmlUtilRs::call('split_qualified_name', [$qname, $defaultNs]);
    }

    function create_comment(string $content)
    {
        return \EverythingRust\NativeXmlUtilRs::call('create_comment', [$content]);
    }

    function create_cdata_section(string $data)
    {
        return \EverythingRust\NativeXmlUtilRs::call('create_cdata_section', [$data]);
    }

    function create_end_element(string $qname)
    {
        return \EverythingRust\NativeXmlUtilRs::call('create_end_element', [$qname]);
    }
}
